using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace Iris {
    public sealed class ShelfAdmission {public readonly List<string> Accepted=new List<string>();public int Rejected,Duplicates,Invalid;}
    public static class ShelfCapacity {
        public const int Limit=4;
        public static ShelfAdmission Plan(IEnumerable<string> existing,IEnumerable<string> incoming,Func<string,bool> exists){var result=new ShelfAdmission();var seen=new HashSet<string>(existing,StringComparer.OrdinalIgnoreCase);int occupied=seen.Count;foreach(string path in incoming){if(string.IsNullOrWhiteSpace(path)||path.Length>32767){result.Invalid++;continue;}if(!seen.Add(path)){result.Duplicates++;continue;}if(occupied>=Limit){result.Rejected++;continue;}bool valid=false;try{valid=exists(path);}catch{}if(!valid){result.Invalid++;continue;}result.Accepted.Add(path);occupied++;}return result;}
    }
    public sealed partial class NotchWindow {
        TextBlock shelfCount,shelfNotice;ScrollViewer shelfScroll;DispatcherTimer shelfNoticeTimer;
        void BuildShelfCount(Grid view){shelfCount=Text("",10,muted);shelfCount.Margin=new Thickness(110,7,0,0);shelfCount.Width=42;shelfCount.HorizontalAlignment=HorizontalAlignment.Left;shelfCount.VerticalAlignment=VerticalAlignment.Top;shelfCount.IsHitTestVisible=true;view.Children.Add(shelfCount);shelfNotice=Text("",10,muted);shelfNotice.Margin=new Thickness(34,123,30,0);shelfNotice.TextAlignment=TextAlignment.Center;shelfNotice.VerticalAlignment=VerticalAlignment.Top;shelfNotice.TextTrimming=TextTrimming.CharacterEllipsis;view.Children.Add(shelfNotice);UpdateShelfCount();}
        void UpdateShelfCount(){if(shelfCount==null)return;shelfCount.Text=prefs.Files.Count+" / 4";shelfCount.ToolTip=prefs.Files.Count>4?L.T("Diese ältere Ablage enthält mehr als vier Verweise. Über die sichtbare waagerechte Bildlaufleiste sind alle erreichbar. Entferne Einträge, bis wieder Platz ist. Originaldateien bleiben erhalten."):L.T("Maximal vier Datei- oder Ordnerverweise. Mehrfachauswahl belegt nur freie Plätze.");if(shelfScroll!=null)shelfScroll.HorizontalScrollBarVisibility=prefs.Files.Count>4?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled;}
        void ShelfNotice(string text){if(shelfNotice==null)return;if(shelfNoticeTimer!=null)shelfNoticeTimer.Stop();shelfNotice.Text=text;shelfCount.ToolTip=text+L.T("\nMaximal vier Einträge; Originaldateien bleiben unverändert.");shelfNoticeTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(6)};shelfNoticeTimer.Tick+=delegate{shelfNoticeTimer.Stop();shelfNotice.Text="";UpdateShelfCount();};shelfNoticeTimer.Start();}
        void StyleShelfScroll(ScrollViewer scroll){var template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type ScrollBar}'><Border Background='#161618' CornerRadius='4'><Track x:Name='PART_Track' Orientation='{TemplateBinding Orientation}' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{TemplateBinding Value}' ViewportSize='{TemplateBinding ViewportSize}'><Track.DecreaseRepeatButton><RepeatButton Command='{x:Static ScrollBar.PageLeftCommand}' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='{x:Type RepeatButton}'><Border Background='Transparent'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType='{x:Type Thumb}'><Border Background='#55555B' CornerRadius='4' Margin='0,1'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command='{x:Static ScrollBar.PageRightCommand}' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='{x:Type RepeatButton}'><Border Background='Transparent'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton></Track></Border></ControlTemplate>");var style=new Style(typeof(System.Windows.Controls.Primitives.ScrollBar));style.Setters.Add(new Setter(Control.TemplateProperty,template));style.Setters.Add(new Setter(FrameworkElement.HeightProperty,8.0));style.Setters.Add(new Setter(Control.MinHeightProperty,8.0));scroll.Resources[typeof(System.Windows.Controls.Primitives.ScrollBar)]=style;scroll.PreviewMouseWheel+=delegate(object sender,System.Windows.Input.MouseWheelEventArgs e){if(prefs.Files.Count>4){scroll.ScrollToHorizontalOffset(scroll.HorizontalOffset-e.Delta*.4);e.Handled=true;}};}
        int AdmitShelfFiles(IEnumerable<string> paths){var admission=ShelfCapacity.Plan(prefs.Files,paths,p=>File.Exists(p)||Directory.Exists(p));prefs.Files.AddRange(admission.Accepted);if(admission.Accepted.Count>0)Save();RefreshShelf();SwitchPage("Ablage",false);Open();int skipped=admission.Rejected+admission.Invalid;if(skipped>0)ShelfNotice(admission.Accepted.Count>0?admission.Accepted.Count+" abgelegt · "+skipped+L.T(" nicht übernommen"):admission.Rejected>0?L.T("Ablage voll · maximal 4 Einträge"):L.T("Keine verfügbare Datei übernommen"));else if(admission.Accepted.Count==0&&admission.Duplicates>0)ShelfNotice(L.T("Bereits in der Ablage"));return admission.Accepted.Count;}
    }
}
